const listBudgets = `-- name: ListBudgets :many
SELECT id, legal_entity_id, code, name_en, name_ar, description_en, description_ar, fiscal_year_id, currency_code, budget_type, status, total_budgeted_amount, total_actual_amount, total_committed_amount, created_by_user_id, approved_by_user_id, approved_at, created_at, updated_at FROM budgeting.budgets
WHERE legal_entity_id = $1
ORDER BY created_at DESC
`

func (q *Queries) ListBudgets(ctx context.Context, legalEntityID pgtype.UUID) ([]BudgetingBudgets, error) {
	rows, err := q.db.Query(ctx, listBudgets, legalEntityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BudgetingBudgets{}
	for rows.Next() {
		var i BudgetingBudgets
		if err := rows.Scan(
			&i.ID,
			&i.LegalEntityID,
			&i.Code,
			&i.NameEn,
			&i.NameAr,
			&i.DescriptionEn,
			&i.DescriptionAr,
			&i.FiscalYearID,
			&i.CurrencyCode,
			&i.BudgetType,
			&i.Status,
			&i.TotalBudgetedAmount,
			&i.TotalActualAmount,
			&i.TotalCommittedAmount,
			&i.CreatedByUserID,
			&i.ApprovedByUserID,
			&i.ApprovedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumBudgetLinesByVersion = `-- name: SumBudgetLinesByVersion :one
SELECT 
    COALESCE(SUM(amount), 0)::NUMERIC(24,6) AS total_budgeted,
    COALESCE(SUM(actual_amount), 0)::NUMERIC(24,6) AS total_actual,
    COALESCE(SUM(committed_amount), 0)::NUMERIC(24,6) AS total_committed
FROM budgeting.budget_lines
WHERE budget_version_id = $1
`

type SumBudgetLinesByVersionRow struct {
	TotalBudgeted  pgtype.Numeric `json:"total_budgeted"`
	TotalActual    pgtype.Numeric `json:"total_actual"`
	TotalCommitted pgtype.Numeric `json:"total_committed"`
}

func (q *Queries) SumBudgetLinesByVersion(ctx context.Context, budgetVersionID pgtype.UUID) (SumBudgetLinesByVersionRow, error) {
	row := q.db.QueryRow(ctx, sumBudgetLinesByVersion, budgetVersionID)
	var i SumBudgetLinesByVersionRow
	err := row.Scan(&i.TotalBudgeted, &i.TotalActual, &i.TotalCommitted)
	return i, err
}

